def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two integers.")

    # Sort the array in descending order
    arr.sort()

    # Calculate the product of the two largest numbers and the product of the two smallest numbers
    max_product = arr[-1] * arr[-2]  # Two largest numbers
    min_product = arr[0] * arr[1]  # Two smallest numbers

    # Return the pair with the highest product
    if max_product >= min_product:
        return (arr[-2], arr[-1])
    else:
        return (arr[0], arr[1])

