def extract_even(data):
    def filter_even(item):
        if isinstance(item, tuple):
            # Recursively process nested tuples
            filtered = tuple(filter_even(sub_item) for sub_item in item)
            return tuple(x for x in filtered if x != ())
        elif isinstance(item, int) and item % 2 == 0:
            # Keep even integers
            return item
        return ()

